/**
 * AgentController - Per-agent pathfinding state machine
 *
 * Per-agent state machine for pathfinding navigation.
 * Manages path computation, following, and arrival detection.
 * Sets force values on the shared buffer for physics integration.
 *
 * **States**
 *
 * - IDLE: No active navigation
 * - PATHFINDING: Computing path
 * - FOLLOWING: Following computed path
 * - ARRIVED: Reached destination
 *
 * **Usage**
 *
 * ```js
 * const agent = new AgentController(bodyIndex, { maxSpeed: 5 });
 * agent.setDestination(targetPos, onArrived, onFailed);
 * agent.update(body, sDynamic, delta, pathFinder);
 * ```
 *
 * @class AgentController
 * @short Per-agent pathfinding state machine
 * @category Core
 * @tags Agent, State Machine, Navigation
 */
export class AgentController {
    /**
     * Create agent controller.
     *
     * @param {number} bodyIndex - Index of the body in physicsState.
     * @param {string} bodyType - Body type ('dynamic' or 'kinematic').
     * @param {Object} [config] - Configuration options.
     * @param {number} [config.maxSpeed=5.0] - Maximum movement speed.
     * @param {number} [config.arrivalRadius=1.5] - Arrival detection radius.
     * @param {number} [config.replanThreshold=5.0] - Replan if blocked for this long.
     * @param {number} [config.rotationSpeed=0.15] - Rotation interpolation speed.
     * @param {number} [config.groundOffset=1.0] - Height offset above ground for kinematic bodies.
     * @param {boolean} [config.useDirectPosition=false] - Use direct position updates instead of forces (for RTS-style movement).
     */
    constructor(bodyIndex: number, bodyType: string, config?: {
        maxSpeed?: number;
        arrivalRadius?: number;
        replanThreshold?: number;
        rotationSpeed?: number;
        groundOffset?: number;
        useDirectPosition?: boolean;
    });
    bodyIndex: number;
    bodyType: string;
    state: number;
    /**
     * Navigation type ('astar' or 'navmesh').
     * @type {string}
     */
    navigationType: string;
    path: any;
    pathIndex: number;
    destination: any;
    steering: SteeringBehavior;
    velocity: any;
    onArrived: Function;
    onPathFailed: Function;
    replanThreshold: number;
    rotationSpeed: number;
    maxPathRetries: any;
    groundOffset: number;
    useDirectPosition: boolean;
    blockedTime: number;
    _lastPosition: any;
    _positionInitialized: boolean;
    pathRetries: number;
    retryDelay: number;
    needsCacheInvalidation: boolean;
    _destinationVersion: number;
    _aiEnabled: boolean;
    _currentAIIntent: any;
    _aiAimTarget: any;
    _aiFireTrigger: boolean;
    /**
     * Configure agent parameters.
     *
     * @param {Object} config - Configuration object.
     * @returns {AgentController} This instance for chaining.
     */
    set(config: any): AgentController;
    /**
     * Enable or disable AI control.
     *
     * @param {boolean} enabled - Whether AI is enabled.
     */
    setAIEnabled(enabled: boolean): void;
    /**
     * Set the current AI intent from the Coordinator.
     *
     * @param {AgentIntent} intent - The AI intent envelope.
     */
    setAIIntent(intent: AgentIntent): void;
    /**
     * Check if AI should fire this frame.
     *
     * @returns {boolean} True if should fire.
     */
    shouldFire(): boolean;
    /**
     * Get the AI aim target position.
     *
     * @returns {Object|null} Aim target { x, y, z } or null.
     */
    getAIAimTarget(): any | null;
    /**
     * Check if AI is enabled.
     *
     * @returns {boolean} True if AI is enabled.
     */
    get aiEnabled(): boolean;
    /**
     * Set navigation destination.
     *
     * @param {THREE.Vector3} destination - Target world position.
     * @param {Function} [onArrived] - Callback when arrived.
     * @param {Function} [onPathFailed] - Callback if no path found.
     */
    setDestination(destination: THREE.Vector3, onArrived?: Function, onPathFailed?: Function, version?: number): void;
    /**
     * Cancel current navigation and reset to idle.
     */
    cancel(): void;
    /**
     * Update agent - called from physics worker each frame.
     *
     * @param {Object} body - Physics body.
     * @param {Object} sBuffer - Shared buffer view (sDynamic or sKinematic).
     * @param {number} delta - Time delta in seconds.
     * @param {PathFinder} pathFinder - Pathfinder instance.
     * @param {Map} agents - Map of all agents for separation calculation.
     */
    update(body: any, sBuffer: any, delta: number, pathFinder: PathFinder, agents: Map<any, any>): void;
    /**
     * Handle arrival at destination.
     *
     * @param {Object} sBuffer - Shared buffer view.
     * @private
     */
    private _handleArrival;
    /**
     * Stop navigation and clear state.
     */
    stop(): void;
    /**
     * Check if agent is currently navigating.
     *
     * @returns {boolean} True if navigating.
     */
    get isNavigating(): boolean;
    /**
     * Check if agent has arrived at destination.
     *
     * @returns {boolean} True if arrived.
     */
    get hasArrived(): boolean;
    /**
     * Get current state name for debugging.
     *
     * @returns {string} State name.
     */
    getStateName(): string;
    /**
     * Handle AI aim rotation when stopped or idle.
     *
     * @param {Object} body - Physics body.
     * @param {Object} sBuffer - Shared buffer view.
     * @param {number} delta - Time delta in seconds.
     * @private
     */
    private _handleAIAim;
}
export namespace AgentState {
    let IDLE: number;
    let PATHFINDING: number;
    let FOLLOWING: number;
    let ARRIVED: number;
}
import { SteeringBehavior } from './SteeringBehavior.js';
